function toast(message){let node=$('cff-account-toast');if(!node){node=document.createElement('div');node.id='cff-account-toast';node.className='cff-account-toast';node.setAttribute('role','status');document.body.append(node);}node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,4500);}
function message(error){const code=String(error?.code||'');return code.includes('operation-not-allowed')?'O login com Google ainda precisa ser ativado pelo administrador.':code.includes('unauthorized-domain')?'Este domínio ainda precisa ser autorizado no Firebase.':code.includes('popup-blocked')?'O navegador bloqueou a janela. Permita o pop-up e tente novamente.':code.includes('popup-closed')||code.includes('cancelled-popup')?'Login cancelado.':code.includes('account-exists-with-different-credential')?'Esta conta já usa outro método de entrada. Entre pelo método original antes de vincular o Google.':code.includes('requires-recent-login')?'Entre novamente com Google para confirmar esta ação.':code.toLowerCase().includes('permission_denied')||code.toLowerCase().includes('permission-denied')?'As permissões da área pessoal ainda estão sendo configuradas. Seus dados não foram apagados.':navigator.onLine===false?'Sem conexão. Tente novamente quando a internet voltar.':'Não foi possível concluir agora. Tente novamente.';}
async function api(path){const r=await fetch(API+path,{cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha ao consultar Instagram');return d;}
function accountRef(path='',uid=user?.uid){if(!uid)throw Error('Entre com Google primeiro.');return ref(database,'userAccounts/'+uid+(path?'/'+path:''));}
async function slugDigits(uid){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(uid||''))),hex=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join(''),digits=BigInt('0x'+hex).toString(10);return (digits+'0000000000').slice(0,10);}
async function ensureProfileSlug(uid){if(!uid)return '';const reverse=ref(database,'communityProfileSlugByUid/'+uid),current=(await get(reverse)).val();if(/^user\d{6,10}$/.test(String(current||'')))return current;const digits=await slugDigits(uid);for(let len=6;len<=10;len++){const slug='user'+digits.slice(0,len),claim=ref(database,'communityProfileSlugs/'+slug),result=await runTransaction(claim,value=>!value||value===uid?uid:undefined);if(result.committed&&result.snapshot.val()===uid){await set(reverse,slug);return slug;}}return '';}
async function profileSlugForUid(uid){try{const value=(await get(ref(database,'communityProfileSlugByUid/'+uid))).val();return /^user\d{6,10}$/.test(String(value||''))?String(value):'';}catch{return '';}}
function profilePath(username='',slug=''){const ig=String(username||'').replace(/^@+/,'').toLowerCase();if(/^[a-z0-9_.]{1,64}$/.test(ig))return '/perfil/@'+ig;if(/^user\d{6,10}$/.test(String(slug||'')))return '/perfil/'+slug;return '/conta.html';}
async function currentProfilePath(){if(communityStatus?.username)return profilePath(communityStatus.username);let slug=profileSlug;try{slug=slug||await ensureProfileSlug(user?.uid);}catch{}if(slug){profileSlug=slug;return profilePath('',slug);}return user?.uid?'/conta.html?u='+encodeURIComponent(user.uid):'/conta.html';}
async function canonicalizePublicProfileUrl(){try{if(viewInstagram){history.replaceState(null,'',profilePath(viewInstagram));return;}const uid=viewUid||publicProfile?.uid;if(uid){const slug=viewSlug||await profileSlugForUid(uid);if(slug)history.replaceState(null,'',profilePath('',slug));}}catch{}}

function button(label,action,cls=''){return `<button type="button" class="cff-account-button ${cls}" data-account-action="${action}">${esc(label)}</button>`;}
function announce(){updateAccountAccess();window.dispatchEvent(new CustomEvent('cff:account-changed',{detail:{signedIn:!!user}}));}
function modal(title,body){let d=$('cff-account-dialog');if(!d){d=document.createElement('dialog');d.id='cff-account-dialog';d.className='cff-account-dialog';document.body.append(d);}d.innerHTML=`<h2>${esc(title)}</h2>${body}<div class="cff-account-actions">${button('Fechar','close')}</div>`;if(!d.open)d.showModal();return d;}
function requireUser(){if(user)return true;modal('Sua conta Central Free Fire',`<p>Entre com Google para salvar e acessar seus dados em outros aparelhos. Ao vincular também seu Instagram, você recebe <strong>+20 pontos</strong> uma única vez.</p><div class="cff-account-actions">${button('Entrar com Google','login','primary')}</div><p><a href="politica-de-privacidade.html">Política de privacidade</a></p>`);return false;}
async function login(){if(!auth||busy)return;busy=true;try{const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});await signInWithPopup(auth,provider);$('cff-account-dialog')?.close();}catch(e){toast(message(e));const status=$('cff-account-login-status');if(status)status.textContent=message(e);}finally{busy=false;}}
async function claimGoogleAccountBonus(silent=true){if(!user||!communityStatus||communityStatus.source==='admin')return null;const doneKey='cff_google_account_bonus_v1_'+user.uid;if(readLocal(doneKey)==='done')return {alreadyClaimed:true};try{const idToken=await user.getIdToken(),response=await fetch(API+'/api/account/google-bonus',{method:'POST',headers:{Authorization:'Bearer '+idToken,'Content-Type':'application/json'},body:'{}'}),data=await response.json();if(!response.ok)throw Error(data.error||'Falha ao liberar bônus');if(data.awarded||data.alreadyClaimed){writeLocal(doneKey,'done');if(data.awarded&&!silent)toast('Conta Google conectada: +'+Number(data.points||20)+' pontos!');return data;}return data;}catch(error){if(!silent)toast('Conta conectada. O bônus será tentado novamente depois.');return null;}}

function setSession(token,uid){const old=readLocal(SESSION);writeLocal(SESSION,token);writeLocal(OWNER,token?uid:'');if(old!==token)window.dispatchEvent(new Event('cff:community-session-changed'));}
async function verifyCommunity(token){if(!/^[a-f0-9]{48}$/i.test(token||''))return null;const result=await api('/api/checkin/status?session='+encodeURIComponent(token));return result.status==='verified'?result:null;}
async function rememberInstagram(token=readLocal(SESSION)){
 if(!requireUser())return false;const uid=user.uid;const ownerLink=await get(ref(database,'communityOwnerInstagram')).then(s=>s.val()).catch(()=>null);if(ownerLink?.uid===uid&&ownerLink?.username==='nakataff'){toast('Este perfil está vinculado a @nakataff pelo admin. Desvincule antes de conectar outro Instagram.');return false;}const status=await verifyCommunity(token);if(!status){toast('Confirme o código no Instagram antes de salvar o vínculo.');return false;}
 if(user?.uid!==uid)return false;await set(accountRef('community',''+uid),{session:token});if(user?.uid!==uid)return false;setSession(token,uid);community={session:token};communityStatus=status;await activity('Instagram vinculado');await syncMember();syncPublicIdentity(true).catch(()=>{});await claimGoogleAccountBonus(false);stats=null;statsState='idle';if($('cff-account-root'))loadProfileStats();toast('Instagram salvo na sua conta Google.');if($('cff-account-root'))await loadLists();else render();return true;
}
async function forgetInstagram(){if(!requireUser())return;if(communityStatus?.source==='admin')await set(ref(database,'communityOwnerInstagram'),null);await set(accountRef('community'),null);community=null;communityStatus=null;stats=null;statsState='idle';historyRows=[];historyLoaded=false;historyState='idle';setSession('',user.uid);await syncMember();render();await syncPublicIdentity().catch(()=>{});await set(ref(database,'communityInstagramLinks/'+user.uid),null);toast('Instagram desvinculado desta conta. Os pontos continuam no ranking.');}
function availableSlot(current,prefix,limit){for(let n=0;n<limit;n++){const id=prefix+n;if(!current?.[id])return id;}return null;}
async function activity(action){if(!user)return;const uid=user.uid;try{await runTransaction(accountRef('activity',uid),current=>{const next={...(current||{})};const slot=availableSlot(next,'a',40)||Object.keys(next).sort((a,b)=>next[a].at-next[b].at)[0];next[slot]={action:String(action).slice(0,120),at:Date.now()};return next;});}catch{/* An optional journal must not block a confirmed save. */}}
async function loadLists(){if(!user)return;const uid=user.uid,seq=++loadGeneration;const values=await Promise.all(Object.keys(lists).map(async key=>[key,(await get(accountRef(key,uid))).val()||{}]));if(user?.uid!==uid||seq!==loadGeneration)return;lists=Object.fromEntries(values);loaded=true;render();}
async function saveFavorite(kind,name,team=''){
 if(!requireUser())return;if(!['team','player'].includes(kind)||!String(name).trim())return;
 const uid=user.uid,item={kind,name:String(name).trim().slice(0,100),team:String(team).trim().slice(0,100),createdAt:Date.now()};
 await runTransaction(accountRef('favorites',uid),current=>{const next={...(current||{})},existing=Object.keys(next).find(key=>next[key].kind===kind&&next[key].name===item.name&&next[key].team===item.team),key=existing||availableSlot(next,'f',100);if(!key)throw Error('Limite de favoritos atingido');next[key]=item;return next;});
 if(user?.uid!==uid)return;await activity('Favorito salvo: '+name);toast('Adicionado aos favoritos.');if($('cff-account-root'))await loadLists();
}
async function saveComparison(snapshot){if(!requireUser())return;if(!snapshot?.players?.length)return;const title=prompt('Nome da comparação:',snapshot.players.map(p=>p.name).join(' × ').slice(0,100));if(!title?.trim())return;const uid=user.uid,item={title:title.trim().slice(0,120),snapshotJson:JSON.stringify(snapshot),createdAt:Date.now()};if(item.snapshotJson.length>50000)throw Error('Comparação muito grande');await runTransaction(accountRef('comparisons',uid),current=>{const next={...(current||{})},key=availableSlot(next,'c',30);if(!key)throw Error('Limite de comparações atingido');next[key]=item;return next;});if(user?.uid!==uid)return;await activity('Comparação salva: '+item.title);toast('Comparação salva na sua conta.');if($('cff-account-root'))await loadLists();}
const cleanTournamentName=name=>String(name||'').trim().slice(0,120);
async function saveTournament(){
 if(!requireUser())return;if(window.__CFF_CAMP_READY__!==true)throw Error('Aguarde o painel carregar.');
 const snapshot=window.CFF_CAMP?.persistence?.saveLocalNow('account-save',true);if(!snapshot?.backup){toast('Monte o torneio antes de salvar na conta.');return;}
 const name=prompt('Nome do torneio salvo:',snapshot.tournamentName||'Meu torneio');if(!name?.trim())return;const backupJson=JSON.stringify(snapshot.backup);if(backupJson.length>1500000){toast('O backup ultrapassa 1,5 MB. Baixe o JSON pelo painel.');return;}
 const uid=user.uid,existing=readLocal('cff_account_tournament_id_'+uid),updatedAt=Date.now(),cleanName=cleanTournamentName(name);let savedId='';
 await runTransaction(accountRef('',uid),current=>{const next={...(current||{})},index={...(next.tournamentIndex||{})},tournaments={...(next.tournaments||{})};const id=index[existing]?.name===cleanName?existing:availableSlot(index,'t',10);if(!id)throw Error('Limite de torneios atingido');index[id]={name:cleanName,updatedAt};tournaments[id]={name:cleanName,backupJson,updatedAt};next.tournamentIndex=index;next.tournaments=tournaments;savedId=id;return next;});
 if(user?.uid!==uid)return;writeLocal('cff_account_tournament_id_'+uid,savedId);await activity('Torneio salvo: '+cleanName);toast('Torneio salvo na sua conta Google.');
}
async function removeItem(kind,id){if(!['favorites','comparisons','tournamentIndex'].includes(kind)||!requireUser())return;if(!confirm('Excluir este item da sua conta?'))return;if(kind==='tournamentIndex')await update(accountRef(),{['tournaments/'+id]:null,['tournamentIndex/'+id]:null});else await set(accountRef(kind+'/'+id),null);await loadLists();}
async function restoreComparison(id){const snapshot=JSON.parse(lists.comparisons[id]?.snapshotJson||'null');if(!snapshot)return;sessionStorage.setItem('cff_account_compare_restore',JSON.stringify(snapshot));location.href='index.html#ffws-br-s2-comparar';}
async function readTournament(id){const item=(await get(accountRef('tournaments/'+id))).val();if(!item)throw Error('Torneio não encontrado');JSON.parse(item.backupJson);return item;}
async function restoreTournament(id){const item=await readTournament(id);if(!confirm('Abrir “'+item.name+'”? O torneio atual no navegador será guardado como cópia de segurança.'))return;const raw=localStorage.getItem('cff_public_camp_v1:ffws_autosave');if(raw)localStorage.setItem('cff_public_camp_v1:account_before_restore',raw);localStorage.setItem('cff_public_camp_v1:ffws_autosave',item.backupJson);localStorage.setItem('cff_account_tournament_id_'+user.uid,id);location.href='camp-ao-vivo.html';}
function download(data,name){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function logout(){await signOut(auth);}
async function exportAccount(){if(!requireUser())return;const data=(await get(accountRef())).val();download(data,'centralfreefire-minha-conta.json');}
async function deleteAccount(){if(!user||!confirm('Excluir sua conta e todos os favoritos, comparações e torneios salvos? Os pontos já obtidos no Instagram continuam no ranking.'))return;const current=user;/* Check recent login before removing data. */if(Date.now()-Date.parse(current.metadata.lastSignInTime)>5*60*1000){toast('Entre novamente com Google antes de excluir a conta.');return;}const slug=profileSlug||await profileSlugForUid(current.uid);await Promise.all([set(accountRef('',current.uid),null),set(ref(database,'communityProfiles/'+current.uid),null),set(ref(database,'communityMembers/'+current.uid),null),slug?set(ref(database,'communityProfileSlugs/'+slug),null):Promise.resolve(),set(ref(database,'communityProfileSlugByUid/'+current.uid),null),communityStatus?.source==='admin'?set(ref(database,'communityOwnerInstagram'),null):Promise.resolve()]);await syncPublicIdentity().catch(()=>{});await set(ref(database,'communityInstagramLinks/'+current.uid),null);await deleteUser(current);toast('Conta excluída.');}
function rowsHtml(kind){const items=Object.entries(lists[kind]||{}).sort(([,a],[,b])=>(b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0));if(!items.length)return '<p class="cff-account-empty">Você ainda não salvou itens aqui.</p>';return `<div class="cff-account-grid">${items.map(([id,item])=>`<article class="cff-account-card"><h3>${esc(item.title||item.name)}</h3>${kind==='favorites'?`<p>${item.kind==='team'?'Equipe':'Jogador'}${item.team?' · '+esc(item.team):''}</p>`:`<p>${esc(new Date(item.updatedAt||item.createdAt).toLocaleDateString('pt-BR'))}</p>`}<div class="cff-account-actions">${kind==='comparisons'?`<button class="cff-account-button primary" data-restore-compare="${esc(id)}">Abrir comparação</button>`:kind==='tournamentIndex'?`<button class="cff-account-button primary" data-restore-tournament="${esc(id)}">Abrir torneio</button><button class="cff-account-button" data-download-tournament="${esc(id)}">Baixar JSON</button>`:''}<button class="cff-account-button danger" data-remove-kind="${kind}" data-remove-id="${esc(id)}">Remover</button></div></article>`).join('')}</div>`;}
function instagramHtml(){return `<h2>Instagram e ranking</h2>${communityStatus?`<p><strong>@${esc(communityStatus.username||'Instagram confirmado')}</strong> · ${communityStatus.source==='admin'?'Conta da página vinculada pelo administrador':'Vínculo confirmado pelo sistema de interação'}.</p><p>Este vínculo acompanha sua conta Google nos outros aparelhos.</p><div class="cff-account-actions"><a class="cff-account-button primary" href="interacoes.html">${communityStatus.source==='admin'?'Ranking da comunidade':'Check-in, palpites e recompensas'}</a>${button('Desvincular','unlink')}</div>`:`<p>Confirme seu Instagram uma vez pelo código enviado no direct para @nakataff. Depois, salve o vínculo na conta Google e receba <strong>+20 pontos</strong> uma única vez.</p><div class="cff-account-actions"><a class="cff-account-button primary" href="interacoes.html">Vincular Instagram</a>${readLocal(SESSION)?button('Salvar vínculo já confirmado','link-instagram'):''}</div>`}`;}
const parsed=(value,fallback=[])=>{try{const d=JSON.parse(value||'null');return Array.isArray(d)?d:fallback;}catch{return fallback;}};
const num=v=>Number.isFinite(Number(v))?Number(v):0,fmt=v=>new Intl.NumberFormat('pt-BR').format(num(v));
function accessFor(p){return p===profile?{ownership,roles}:publicProfile||{};}
function avatarId(p=profile,g=grants){const id=p.avatarId||'default',a=accessFor(p);return findOption(options,id)||catalogAvailable(catalog[id],g,a.ownership,a.roles,id)?id:'default';}
function avatar(p=profile,g=grants,cls='cff-profile-avatar'){const id=avatarId(p,g),custom=catalog[id]?.kind==='avatar';return approvedImage(options,catalog,id,cls+(custom?' cff-profile-avatar-art':''),'Avatar de '+(p.name||'torcedor'));}
function teamIds(p=profile){return parsed(p.teamIdsJson).filter(id=>options.teams.some(t=>t.id===id)).slice(0,14);}
function teamMarks(p=profile){return teamIds(p).sort((a,b)=>(b===p.mainTeam)-(a===p.mainTeam)).map(id=>{const t=findOption(options,id);return `<span class="cff-team-chip${id===p.mainTeam?' is-main':''}" title="${id===p.mainTeam?'Time principal':'Time favorito'}">${approvedImage(options,catalog,id,'',t.name)}${esc(t.short)}</span>`;}).join('');}
function theme(p=profile){return ['cyan','gold','pink','green','violet'].includes(p.theme)?p.theme:'cyan';}
function hasCover(p=profile,g=grants){const item=catalog[p.coverId],a=accessFor(p);return Boolean(item?.kind==='cover'&&catalogAvailable(item,g,a.ownership,a.roles,p.coverId));}
function cover(p=profile,g=grants){return hasCover(p,g)?`<div class="cff-profile-cover-art">${approvedImage(options,catalog,p.coverId,'','Capa do perfil')}</div>`:'';}
const cameraSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8.7 4 7.3 6H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-3.3L15.3 4H8.7ZM12 9a4 4 0 1 1 0 8 4 4 0 0 1 0-8Zm0 2a2 2 0 1 0 0 4 2 2 0 0 0 0-4Z"/></svg>';
function avatarControl(p=profile,g=grants,own=true){return `<div class="cff-profile-avatar-wrap">${avatar(p,g)}${own?`<button type="button" class="cff-profile-avatar-edit" data-account-action="avatar-picker" aria-label="Trocar foto de perfil" title="Trocar foto de perfil">${cameraSvg}</button>`:''}</div>`;}
const AVATAR_CATEGORY_LABELS={players:'Jogadores',character:'Personagens',simple:'Simples',stylized:'Estilizadas',special:'Especiais'};
function visualCategoryFor(id){if(options.players.some(x=>x.id===id))return'players';if(id==='default'||options.teams.some(x=>x.id===id))return'simple';const item=catalog[id];return ['character','simple','stylized','special'].includes(item?.category)?item.category:'special';}
function avatarVisualItems(category){
 if(category==='players')return options.players.map(x=>({id:x.id,name:x.name,custom:false,locked:false}));
 const custom=Object.entries(catalog).filter(([,x])=>x.enabled&&x.kind==='avatar'&&(x.category||'special')===category).map(([id,x])=>({id,name:x.title,custom:true,locked:!catalogAvailable(x,grants,ownership,roles,id),lockLabel:ACCESS_LABELS[x.accessRule]||'Bloqueado'}));
 if(category==='simple')return [{id:'default',name:'Central Free Fire',custom:false,locked:false},...options.teams.map(x=>({id:x.id,name:x.name,custom:false,locked:false})),...custom];
 return custom;
}
function visualTile(item,selected,kind='avatar'){const active=item.id===selected,locked=item.locked;return `<button type="button" class="cff-visual-item${item.custom?' is-custom':''}${active?' is-selected':''}" data-visual-pick="${esc(item.id)}" data-visual-kind="${kind}"${locked?' disabled':''}>${approvedImage(options,catalog,item.id,'',item.name)}<span>${esc(item.name)}</span>${active?'<small>Em uso</small>':locked?`<small>🔒 ${esc(item.lockLabel||'Bloqueado')}</small>`:''}</button>`;}
function renderAvatarVisualGrid(dialog,category){const grid=dialog.querySelector('.cff-visual-grid');if(!grid)return;const items=avatarVisualItems(category);grid.innerHTML=items.map(x=>visualTile(x,avatarId(),'avatar')).join('')||'<p class="cff-visual-empty">Nenhuma imagem nesta categoria ainda.</p>';hydrateProfileImages(grid,database);dialog.querySelectorAll('[data-visual-category]').forEach(b=>b.classList.toggle('is-active',b.dataset.visualCategory===category));dialog.querySelectorAll('[data-visual-pick]').forEach(b=>b.addEventListener('click',()=>saveVisualSelection('avatar',b.dataset.visualPick)));}
